import { isIP } from 'node:net';

// createServer({ ..., trustedProxyHops = 0 })
function clientAddress(request) {
  if (trustedProxyHops > 0) {
    const hops = String(request.headers['x-forwarded-for'] || '').split(',').map(value => value.trim()).filter(Boolean);
    const candidate = hops[hops.length - trustedProxyHops];
    if (candidate && isIP(candidate)) return candidate;
  }
  return request.socket.remoteAddress;
}

function rateLimit(request, scope) {
  const now = Date.now();
  const key = `${scope}|${clientAddress(request)}`;
  const current = attempts.get(key);
  if (current && current.until > now) {
    if (++current.count > 30) throw new HttpError(429, 'Try again shortly');
  } else {
    attempts.set(key, { count: 1, until: now + 60_000 });
    for (const [entry, attempt] of attempts) if (attempt.until <= now) attempts.delete(entry);
  }
}
// call sites: rateLimit(request, 'bootstrap'), rateLimit(request, 'pairing'), rateLimit(request, 'reveal')
